import style from './KeepInSync.module.scss'
import cards from '../../assets/png/keepInSync_cards.png'
import {TitleWithLines} from "../_common/TitleWithLines/TitleWithLines";
export const KeepInSync = () => {
    return (
        <div className={style.keepInSync}>
            <div className={style.inner}>

                <img src={cards} alt=""/>

                <div className={style.bottom}>

                    <TitleWithLines title='Keep In Sync' onlyRight={true}/>

                    <h2 className={style.title}>
                        Seamlessly Launch on Pumpfun
                    </h2>

                    <p className={style.text}>
                        Execute token launches directly on Pumpfun via chat, generate logos instantly, and enjoy a secure, efficient launch process.
                    </p>

                </div>


            </div>
        </div>
    )
}