import style from './TitleWithLines.module.scss'
import {FC} from "react";
import {clsx} from "clsx";

interface ITitleWithLines {
    title: string
    onlyRight?: boolean
}

export const TitleWithLines: FC<ITitleWithLines> = ({
                                                        title,
                                                        onlyRight = false
                                                    }) => {
    return (
        <div className={clsx({
            [style.titleWithLines]: true,
            [style.titleWithLines_onlyRight]: onlyRight,
        })}>
            {!onlyRight && <div className={style.left}/>}
            <p>{title}</p>
            <div className={style.right}/>
        </div>
    )
}