import style from './TakeControl.module.scss'
// @ts-ignore
import scene from '../../assets/spline/scene.splinecode';
import Spline from "@splinetool/react-spline";
import {WalletButtons} from "../_common/WalletButtons/WalletButtons";

export const TakeControl = () => {
    return (
        <div className={style.takeControl}>

            <div className={style.splineWrapper}>
                <Spline scene={scene}/>
            </div>

            <div className={style.mask}/>

            <div className={style.inner}>

                <h1 className={style.title}>
                    <p>Take <span>Control of</span></p>
                    <div>
                        <p>Crypto Markets</p>
                        <p>with XZYPHER</p>
                    </div>
                </h1>

                <p className={style.description}>
                    Use a chat-based interface to blend on-chain and social data, enabling smarter trading decisions.
                </p>

                <button className={style.launchChat}>
                    <span>Launch Chat</span>
                </button>

                <WalletButtons className={style.walletButtons}/>

                <p className={style.version}>
                    *Current Version 1.2 is capable of performing the functions listed above*
                </p>

            </div>

        </div>
    )
}