import style from './MeetXZYPHER.module.scss';
import {TitleWithLines} from "../_common/TitleWithLines/TitleWithLines";
import {TopCards} from "./TopCards/TopCards";
import {BottomCards} from "./BottomCards/BottomCards";
import back from '../../assets/png/meet_background.png';

export const MeetXZYPHER = () => {
    return (
        <div className={style.meetXZYPHER}>

            <img src={back} alt="" className={style.back}/>

            <div className={style.inner}>
                <TitleWithLines title='Meet XZYPHER'/>
                <h2 className={style.title}>
                    Real-Time Chat-to-Blockchain Intelligence
                </h2>
                <p className={style.text}>
                    This AI agent executes tasks like token swaps, Solana deployments, Pumpfun launches, and retrieving token details.
                </p>

                <TopCards/>
                <BottomCards/>
            </div>
        </div>
    )
}