import style from './Features.module.scss'
import {TitleWithLines} from "../_common/TitleWithLines/TitleWithLines";
import back from '../../assets/png/features/background.png';
import {clsx} from "clsx";
import items from '../../assets/png/features/items.png';
import iphone from '../../assets/png/features/iphone.png';
import graph_m from '../../assets/png/features/graph_m.png';
import graph_d from '../../assets/png/features/graph_d.png';

export const Features = () => {
    return (
        <div className={style.features}
             id='Features'
        >

            <img src={back} alt="" className={style.back}/>

            <div className={style.inner}>
                <TitleWithLines title='Features'/>
                <h2 className={style.title}>
                    Core Features for Crypto Success
                </h2>
                <p className={style.text}>
                    XZYPHER delivers advanced insights by combining on-chain activity and real-time data analysis,
                    enabling smarter token swaps and deployments.
                </p>

                <div className={clsx(style.card, style.top)}>
                    <div className={style.texts}>
                        <p>Streamline Everyday Actions</p>
                        <p>It simplifies routine processes like token swaps and launches, allowing you to complete tasks
                            efficiently and stay focused on what matters.</p>
                    </div>
                    <div className={style.items}>
                        <img src={items} alt=""/>
                    </div>
                </div>

                <div className={style.bottom}>
                    <div className={style.card}>
                        <img src={iphone} alt=""/>
                        <p>
                            Swap tokens instantly with XZYPHER’S AI and Jupiter API
                        </p>
                    </div>
                    <div className={style.card}>
                        <img src={graph_m} alt=""/>
                        <img src={graph_d} alt=""/>
                        <p>
                            Analyze token data powered by Send AI and Blink
                        </p>
                    </div>
                </div>


            </div>


        </div>
    )
}