import React, {useEffect, useState} from 'react';
import {Route, Routes} from "react-router-dom";
import {HomePage} from "../B0_HomePage/HomePage";
import {ChatPage} from "../C0_ChatPage/ChatPage";
import style from './App.module.scss'
import {Header} from "../A1_Header/Header";
import {clsx} from "clsx";
import {Preloader} from "../A3_Preloader/Preloader";
import {observer} from "mobx-react-lite";
import {useStore} from "../../store/rootStore";
import {Footer} from "../A2_Footer/Footer";

export const App = observer(() => {

    const {
        appStore: {
            burgerMenuOpen
        }
    } = useStore()

    const [showPreloader, setShowPreloader] = useState(true);

    useEffect(() => {
        const timer = setTimeout(() => {
            setShowPreloader(false)
        }, 3000)
        return () => clearTimeout(timer);
    }, []);

    return (
        <div className={clsx({
            [style.app]: true,
            [style.app_showPreloader]: showPreloader || burgerMenuOpen,
        })}>

            {showPreloader && <Preloader/>}

            <Header/>

            <Routes>
                <Route path='/' element={<HomePage/>}/>
                <Route path='/chat' element={<ChatPage/>}/>
            </Routes>

            <Footer/>

        </div>
    );
})
