import style from './Instant.module.scss'
import {TitleWithLines} from "../_common/TitleWithLines/TitleWithLines";
import back from '../../assets/png/instant_back.png';
import open_ai from '../../assets/png/open_ai.png';
import dialect from '../../assets/png/dialect.png';
import solana_agent_kit from '../../assets/png/solana_agent_kit.png';


export const Instant = () => {
    return (
        <div className={style.instant}>

            <img src={back} alt="" className={style.back}/>

            <div className={style.inner}>

                <TitleWithLines title='Instant Cross-Chain Liquidity'/>

                <h2 className={style.title}>
                    Effortlessly Manage Assets Across Chains
                </h2>

                <p className={style.text}>
                    Seamlessly manage swaps, liquidity pools, and tokens across Solana, Ethereum, and other networks
                    from your Chat agent connected to your Phantom wallet.
                </p>

                <p className={style.cardsTitle}>
                    Powered by Innovation in AI
                </p>

                <div className={style.cards}>
                    {
                        [open_ai, solana_agent_kit, dialect].map((src, key) => (
                            <div key={key}>
                                <img src={src} alt=""/>
                            </div>
                        ))
                    }

                </div>

            </div>

        </div>
    )
}