import {FC} from "react";
import {clsx} from "clsx";
import style from './WalletButtons.module.scss';
import {svgIcons} from "../../../assets/svgIcons";
import pumpFun from '../../../assets/png/pumpFun.png';

interface IWalletButtons {
    className?: string
}

export const WalletButtons: FC<IWalletButtons> = ({className}) => {
    return (
        <div className={clsx(style.walletButtons, Boolean(className) && className)}>
            <button>
                {svgIcons.solana}
                <p>Create Token On Solana</p>
            </button>
            <button>
                <img src={pumpFun} alt=""/>
                <p>Create + Launch On PumpFun</p>
            </button>
            <button>
                {svgIcons.jupiter}
                <p>Swap on Jupiter</p>
            </button>
        </div>
    )
}